target.css:
:root {
  --ink: #253038;
  --paper: #fffdf7;
  --line: #d8d1c4;
  --stamp: #db5a42;
  --muted: #747a78;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  color: var(--ink);
}

.station-pass {
  width: 460px;
  padding: 22px 24px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.pass-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 17px;
  border-bottom: 1px dashed var(--line);
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.15;
}

.status {
  padding: 5px 8px;
  color: var(--paper);
  background: var(--stamp);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.details {
  display: flex;
  gap: 30px;
  margin-top: 16px;
}

.details p {
  margin: 0;
}

.details span {
  display: block;
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.details strong {
  font-size: 15px;
}
